Inductive CallKind := Call | CallCode | DelegateCall | StaticCall.
Definition num_of_CallKind (arg_ : CallKind) : Z :=
   match arg_ with | Call => 0 | CallCode => 1 | DelegateCall => 2 | StaticCall => 3 end.

Definition CallKind_of_num (arg_ : Z) (*(0 <=? arg_) && (arg_ <=? 3)*) : CallKind :=
   let l__0 := arg_ in
   if Z.eqb (l__0) (0) then Call
   else if Z.eqb (l__0) (1) then CallCode
   else if Z.eqb (l__0) (2) then DelegateCall
   else StaticCall.

Lemma CallKind_num_of_roundtrip (x : CallKind) : CallKind_of_num (num_of_CallKind x) = x.
  destruct x; reflexivity.
Qed.
Lemma num_of_CallKind_injective (x y : CallKind) : num_of_CallKind x = num_of_CallKind y -> x = y.
  intro.
  rewrite <- (CallKind_num_of_roundtrip x).
  rewrite <- (CallKind_num_of_roundtrip y).
  congruence.
Qed.
Definition CallKind_eq_dec (x y : CallKind) : {x = y} + {x <> y}.
  refine (match Z.eq_dec (num_of_CallKind x) (num_of_CallKind y) with
  | left e => left (num_of_CallKind_injective x y e)
  | right ne => right _
  end).
  congruence.
Defined.
Definition CallKind_beq (x y : CallKind) : bool :=
  Z.eqb (num_of_CallKind x) (num_of_CallKind y).
Lemma CallKind_beq_iff x y : CallKind_beq x y = true <-> x = y.
  unfold CallKind_beq.
  rewrite Z.eqb_eq.
  split; [apply num_of_CallKind_injective | congruence].
Qed.
Lemma CallKind_beq_refl x : CallKind_beq x x = true.
apply CallKind_beq_iff; reflexivity.
Qed.
#[export]
Instance Decidable_eq_CallKind : EqDecision CallKind := CallKind_eq_dec.
#[export]
Instance Countable_CallKind : Countable CallKind.
refine {|
  encode x := encode (num_of_CallKind x);
  decode x := z ← decode x; mret (CallKind_of_num z);
|}.
abstract (
  intro s; rewrite decode_encode;
  simpl;
  rewrite CallKind_num_of_roundtrip;
  reflexivity).
Defined.
#[export]
Instance dummy_CallKind : Inhabited CallKind := { inhabitant := Call }.


Inductive CreateKind := CreateByNonce | CreateBySalt.
Definition num_of_CreateKind (arg_ : CreateKind) : Z :=
   match arg_ with | CreateByNonce => 0 | CreateBySalt => 1 end.

Definition CreateKind_of_num (arg_ : Z) (*(0 <=? arg_) && (arg_ <=? 1)*) : CreateKind :=
   let l__0 := arg_ in
   if Z.eqb (l__0) (0) then CreateByNonce
   else CreateBySalt.

Lemma CreateKind_num_of_roundtrip (x : CreateKind) : CreateKind_of_num (num_of_CreateKind x) = x.
  destruct x; reflexivity.
Qed.
Lemma num_of_CreateKind_injective (x y : CreateKind) : num_of_CreateKind x = num_of_CreateKind y -> x = y.
  intro.
  rewrite <- (CreateKind_num_of_roundtrip x).
  rewrite <- (CreateKind_num_of_roundtrip y).
  congruence.
Qed.
Definition CreateKind_eq_dec (x y : CreateKind) : {x = y} + {x <> y}.
  refine (match Z.eq_dec (num_of_CreateKind x) (num_of_CreateKind y) with
  | left e => left (num_of_CreateKind_injective x y e)
  | right ne => right _
  end).
  congruence.
Defined.
Definition CreateKind_beq (x y : CreateKind) : bool :=
  Z.eqb (num_of_CreateKind x) (num_of_CreateKind y).
Lemma CreateKind_beq_iff x y : CreateKind_beq x y = true <-> x = y.
  unfold CreateKind_beq.
  rewrite Z.eqb_eq.
  split; [apply num_of_CreateKind_injective | congruence].
Qed.
Lemma CreateKind_beq_refl x : CreateKind_beq x x = true.
apply CreateKind_beq_iff; reflexivity.
Qed.
#[export]
Instance Decidable_eq_CreateKind : EqDecision CreateKind := CreateKind_eq_dec.
#[export]
Instance Countable_CreateKind : Countable CreateKind.
refine {|
  encode x := encode (num_of_CreateKind x);
  decode x := z ← decode x; mret (CreateKind_of_num z);
|}.
abstract (
  intro s; rewrite decode_encode;
  simpl;
  rewrite CreateKind_num_of_roundtrip;
  reflexivity).
Defined.
