Inductive EnvField :=
  | F_Number
  | F_Timestamp
  | F_Coinbase
  | F_BaseFee
  | F_ChainId
  | F_GasLimit
  | F_PrevRandao
  | F_Origin
  | F_GasPrice
  | F_SlotNumber.
Definition num_of_EnvField (arg_ : EnvField) : Z :=
   match arg_ with
   | F_Number => 0
   | F_Timestamp => 1
   | F_Coinbase => 2
   | F_BaseFee => 3
   | F_ChainId => 4
   | F_GasLimit => 5
   | F_PrevRandao => 6
   | F_Origin => 7
   | F_GasPrice => 8
   | F_SlotNumber => 9
   end.

Definition EnvField_of_num (arg_ : Z) (*(0 <=? arg_) && (arg_ <=? 9)*) : EnvField :=
   let l__0 := arg_ in
   if Z.eqb (l__0) (0) then F_Number
   else if Z.eqb (l__0) (1) then F_Timestamp
   else if Z.eqb (l__0) (2) then F_Coinbase
   else if Z.eqb (l__0) (3) then F_BaseFee
   else if Z.eqb (l__0) (4) then F_ChainId
   else if Z.eqb (l__0) (5) then F_GasLimit
   else if Z.eqb (l__0) (6) then F_PrevRandao
   else if Z.eqb (l__0) (7) then F_Origin
   else if Z.eqb (l__0) (8) then F_GasPrice
   else F_SlotNumber.

Lemma EnvField_num_of_roundtrip (x : EnvField) : EnvField_of_num (num_of_EnvField x) = x.
  destruct x; reflexivity.
Qed.
Lemma num_of_EnvField_injective (x y : EnvField) : num_of_EnvField x = num_of_EnvField y -> x = y.
  intro.
  rewrite <- (EnvField_num_of_roundtrip x).
  rewrite <- (EnvField_num_of_roundtrip y).
  congruence.
Qed.
Definition EnvField_eq_dec (x y : EnvField) : {x = y} + {x <> y}.
  refine (match Z.eq_dec (num_of_EnvField x) (num_of_EnvField y) with
  | left e => left (num_of_EnvField_injective x y e)
  | right ne => right _
  end).
  congruence.
Defined.
Definition EnvField_beq (x y : EnvField) : bool :=
  Z.eqb (num_of_EnvField x) (num_of_EnvField y).
Lemma EnvField_beq_iff x y : EnvField_beq x y = true <-> x = y.
  unfold EnvField_beq.
  rewrite Z.eqb_eq.
  split; [apply num_of_EnvField_injective | congruence].
Qed.
Lemma EnvField_beq_refl x : EnvField_beq x x = true.
apply EnvField_beq_iff; reflexivity.
Qed.
#[export]
Instance Decidable_eq_EnvField : EqDecision EnvField := EnvField_eq_dec.
#[export]
Instance Countable_EnvField : Countable EnvField.
refine {|
  encode x := encode (num_of_EnvField x);
  decode x := z ← decode x; mret (EnvField_of_num z);
|}.
abstract (
  intro s; rewrite decode_encode;
  simpl;
  rewrite EnvField_num_of_roundtrip;
  reflexivity).
Defined.
#[export]
Instance dummy_EnvField : Inhabited EnvField := { inhabitant := F_Number }.


