    Build_SstoreCosts f0 f1 e f3 end (at level 1).
Notation "{[ r 'with' 'SstoreCosts_state_credit' := e ]}" :=
  match r with Build_SstoreCosts (_ as f0) (_ as f1) (_ as f2) _ =>
