Notation "{[ r 'with' 'PrecompileResult_output' := e ]}" :=
  match r with Build_PrecompileResult (_ as f0) _ => Build_PrecompileResult f0 e end (at level 1).
#[export]
Instance dummy_PrecompileResult : Inhabited (PrecompileResult) := {
  inhabitant := {| PrecompileResult_success := inhabitant; PrecompileResult_output := inhabitant
|} }.


