  | Some (78, x') => opcode_CREATE <$> decode x'
  | Some (79, x') => CALL <$> decode x'
  | Some (80, x') => CALLCODE <$> decode x'
  | Some (81, x') => RETURN <$> decode x'
  | Some (82, x') => DELEGATECALL <$> decode x'
  | Some (83, x') => CREATE2 <$> decode x'
