  | R_gas _ => encode
  | R_gas_refund _ => encode
  | R_hash _ => encode
  | R_state_gas_spill _ => encode
  end;
  decode := match r with
  | R_BlockHeader _ => decode
  | R_CalldataSlice _ => decode
  | R_Code _ => decode
  | R_EvmMemorySlice _ => decode
  | R_ExecutionProfile _ => decode
  | R_FrameStatus _ => decode
